 51→// DetectPresence checks if Kiro is configured in the repository.
 52→func (k *KiroAgent) DetectPresence(ctx context.Context) (bool, error) {
 53→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 54→	if err != nil {
