 63→// --- Transcript Storage ---
 64→
 65→// ReadTranscript reads the cached transcript JSON for a session.
 66→func (k *KiroAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 67→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path from agent hook
 68→	if err != nil {
 69→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 70→	}
 71→	return data, nil
 72→}
 73→
 74→// ChunkTranscript splits a JSON transcript into chunks.
 75→// Kiro transcripts are single JSON objects; we use the JSONL chunker since the
 76→// cached format is a JSON blob that fits in a single chunk in most cases.
 77→func (k *KiroAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
 78→	if len(content) <= maxSize {
 79→		return [][]byte{content}, nil
 80→	}
 81→	// For large transcripts, split at line boundaries
 82→	chunks, err := agent.ChunkJSONL(content, maxSize)
 83→	if err != nil {
 84→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 85→	}
 86→	return chunks, nil
 87→}
 88→
 89→// ReassembleTranscript combines transcript chunks back into a single blob.
 90→func (k *KiroAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 91→	if len(chunks) == 1 {
 92→		return chunks[0], nil
 93→	}
 94→	return agent.ReassembleJSONL(chunks), nil
 95→}
