104→// GetSessionDir returns the directory where Kiro stores session data.
105→// For Kiro, sessions are in SQLite, but we cache transcripts to .entire/tmp/.
106→func (k *KiroAgent) GetSessionDir(repoPath string) (string, error) {
107→	return filepath.Join(repoPath, ".entire", "tmp"), nil
