115→// ReadSession reads session data from the cached transcript.
116→func (k *KiroAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
117→	if input.SessionRef == "" {
118→		return nil, errors.New("session reference (transcript path) is required")
119→	}
120→
121→	data, err := os.ReadFile(input.SessionRef)
122→	if err != nil {
123→		return nil, fmt.Errorf("failed to read transcript: %w", err)
124→	}
125→
126→	return &agent.AgentSession{
127→		SessionID:  input.SessionID,
128→		AgentName:  k.Name(),
129→		SessionRef: input.SessionRef,
130→		StartTime:  time.Now(),
131→		NativeData: data,
132→	}, nil
133→}
134→
135→// WriteSession writes session data for resumption.
136→func (k *KiroAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
137→	if session == nil {
138→		return errors.New("session is nil")
139→	}
140→	if session.AgentName != "" && session.AgentName != k.Name() {
141→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, k.Name())
142→	}
143→	if session.SessionRef == "" {
144→		return errors.New("session reference (transcript path) is required")
145→	}
146→	if len(session.NativeData) == 0 {
147→		return errors.New("session has no native data to write")
148→	}
149→
150→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
151→		return fmt.Errorf("failed to create session dir: %w", err)
152→	}
153→
154→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
155→		return fmt.Errorf("failed to write transcript: %w", err)
156→	}
157→	return nil
158→}
