170→// --- TranscriptAnalyzer interface implementation ---
171→
172→// errTranscriptEmpty is returned when the transcript file is missing or empty.
173→var errTranscriptEmpty = errors.New("transcript is empty or missing")
174→
175→// readAndParseTranscript reads and parses a Kiro transcript file.
176→// Returns errTranscriptEmpty if the file doesn't exist or is empty.
177→func readAndParseTranscript(path string) (*kiroTranscript, error) {
178→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
179→	if err != nil {
180→		if os.IsNotExist(err) {
181→			return nil, errTranscriptEmpty
182→		}
183→		return nil, fmt.Errorf("reading transcript: %w", err)
184→	}
185→	if len(data) == 0 {
186→		return nil, errTranscriptEmpty
187→	}
188→	t, err := parseTranscript(data)
189→	if err != nil {
190→		return nil, fmt.Errorf("parsing transcript: %w", err)
191→	}
192→	return t, nil
193→}
194→
195→// GetTranscriptPosition returns the number of history entries in a Kiro transcript.
196→// Kiro uses JSON format with paired user+assistant history entries, so position
197→// is the entry count. Returns 0 if the file doesn't exist, is empty, or is a
198→// placeholder "{}".
199→func (k *KiroAgent) GetTranscriptPosition(path string) (int, error) {
200→	if path == "" {
201→		return 0, nil
202→	}
203→	t, err := readAndParseTranscript(path)
204→	if errors.Is(err, errTranscriptEmpty) {
205→		return 0, nil
206→	}
207→	if err != nil {
208→		return 0, err
209→	}
210→	return len(t.History), nil
211→}
212→
213→// ExtractModifiedFilesFromOffset extracts files modified since a given history index.
214→// For Kiro (JSON format), offset is the starting history entry index.
215→func (k *KiroAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
216→	if path == "" {
217→		return nil, 0, nil
218→	}
219→	t, parseErr := readAndParseTranscript(path)
220→	if errors.Is(parseErr, errTranscriptEmpty) {
221→		return nil, 0, nil
222→	}
223→	if parseErr != nil {
224→		return nil, 0, parseErr
225→	}
226→
227→	totalEntries := len(t.History)
228→	if startOffset >= totalEntries {
229→		return nil, totalEntries, nil
230→	}
231→
232→	modifiedFiles := extractModifiedFilesFromHistory(t.History[startOffset:])
233→	return modifiedFiles, totalEntries, nil
234→}
235→
236→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
237→// Only Prompt-type user messages are returned; ToolUseResults entries are skipped.
238→func (k *KiroAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
239→	t, err := readAndParseTranscript(sessionRef)
240→	if err != nil {
241→		return nil, err
242→	}
243→
244→	var prompts []string
245→	for i := fromOffset; i < len(t.History); i++ {
246→		if prompt := extractUserPrompt(t.History[i].User.Content); prompt != "" {
247→			prompts = append(prompts, prompt)
248→		}
249→	}
250→	return prompts, nil
251→}
252→
253→// ExtractSummary extracts the last assistant response as a session summary.
254→func (k *KiroAgent) ExtractSummary(sessionRef string) (string, error) {
255→	t, err := readAndParseTranscript(sessionRef)
256→	if err != nil {
257→		return "", err
258→	}
259→	return extractLastAssistantResponse(t.History), nil
260→}
