262→// --- SQLite helpers ---
263→
264→// escapeSQLString escapes single quotes for use in SQLite string literals.
265→func escapeSQLString(s string) string {
266→	return strings.ReplaceAll(s, "'", "''")
267→}
268→
269→// --- SQLite session resolution ---
270→
271→// dbPath returns the path to Kiro's SQLite database.
272→func dbPath() (string, error) {
273→	home, err := os.UserHomeDir()
274→	if err != nil {
275→		return "", fmt.Errorf("failed to get home directory: %w", err)
276→	}
277→	switch runtime.GOOS {
278→	case "darwin":
279→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
280→	default: // linux
281→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
282→	}
283→}
284→
285→// querySessionID queries the SQLite database for the most recent conversation ID
286→// associated with the given CWD.
287→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
288→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
289→		return "mock-session-id", nil
290→	}
291→
292→	db, err := dbPath()
293→	if err != nil {
294→		return "", err
295→	}
296→	if _, err := os.Stat(db); err != nil {
297→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
298→	}
299→
300→	query := fmt.Sprintf(
301→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
302→		escapeSQLString(cwd),
303→	)
304→
305→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
306→	out, err := cmd.Output()
307→	if err != nil {
308→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
309→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
310→	}
311→
312→	result := strings.TrimSpace(string(out))
313→	if result == "" || result == "[]" {
314→		return "", nil
315→	}
316→
317→	// sqlite3 -json returns an array of objects
318→	var rows []map[string]string
319→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
320→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
321→	}
322→	if len(rows) == 0 {
323→		return "", nil
324→	}
325→
326→	// The column name from json_extract
327→	for _, v := range rows[0] {
328→		return v, nil
329→	}
330→	return "", nil
331→}
332→
333→// ensureCachedTranscript fetches the conversation from SQLite and caches it
334→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
335→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
336→	repoRoot, err := paths.WorktreeRoot(ctx)
337→	if err != nil {
338→		repoRoot = cwd
339→	}
340→
341→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
342→	cachePath := filepath.Join(cacheDir, sessionID+".json")
343→
344→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
345→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
346→		// In test mode, return the expected cache path without hitting SQLite.
347→		return cachePath, nil
348→	}
349→
350→	db, err := dbPath()
351→	if err != nil {
352→		return "", err
353→	}
354→
355→	query := fmt.Sprintf(
356→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
357→		escapeSQLString(cwd),
358→	)
359→
360→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
361→	out, err := cmd.Output()
362→	if err != nil {
363→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
364→	}
365→
366→	transcript := strings.TrimSpace(string(out))
367→	if transcript == "" {
368→		return "", errors.New("no transcript found")
369→	}
370→
371→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
372→		return "", fmt.Errorf("failed to create cache dir: %w", err)
373→	}
374→
375→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
376→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
377→	}
378→
379→	return cachePath, nil
380→}
381→
382→// --- IDE transcript discovery ---
383→
384→// ideWorkspaceSessionsDir returns the directory where the Kiro IDE stores
385→// session files for the given working directory. The directory is derived from
386→// the base64-encoded CWD.
387→func ideWorkspaceSessionsDir(cwd string) (string, error) {
388→	home, err := os.UserHomeDir()
389→	if err != nil {
390→		return "", fmt.Errorf("failed to get home directory: %w", err)
391→	}
392→
393→	encoded := base64.StdEncoding.EncodeToString([]byte(cwd))
394→
395→	var baseDir string
396→	switch runtime.GOOS {
397→	case "darwin":
398→		baseDir = filepath.Join(home, "Library", "Application Support", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
399→	default: // linux
400→		baseDir = filepath.Join(home, ".config", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
401→	}
402→
403→	return filepath.Join(baseDir, encoded), nil
404→}
405→
406→// ensureIDETranscript looks for the most recent Kiro IDE session transcript
407→// for the given CWD and copies it to .entire/tmp/<sessionID>.json.
408→// Returns the cache path on success, or empty string if no transcript is found.
409→func (k *KiroAgent) ensureIDETranscript(ctx context.Context, cwd, sessionID string) (string, error) {
410→	sessDir, err := ideWorkspaceSessionsDir(cwd)
411→	if err != nil {
412→		return "", err
413→	}
414→
415→	// Read the sessions.json index.
416→	indexPath := filepath.Join(sessDir, "sessions.json")
417→	indexData, err := os.ReadFile(indexPath) //nolint:gosec // Controlled path from IDE storage
418→	if err != nil {
419→		logging.Debug(ctx, "kiro: IDE sessions.json not found", "path", indexPath, "err", err)
420→		return "", fmt.Errorf("IDE sessions.json not found: %w", err)
421→	}
422→
423→	var sessions []kiroIDESessionEntry
424→	if err := json.Unmarshal(indexData, &sessions); err != nil {
425→		return "", fmt.Errorf("failed to parse IDE sessions.json: %w", err)
426→	}
427→
428→	if len(sessions) == 0 {
429→		return "", errors.New("no IDE sessions found")
430→	}
431→
432→	// Sort by dateCreated descending to find the most recent session.
433→	sort.Slice(sessions, func(i, j int) bool {
434→		return sessions[i].DateCreated > sessions[j].DateCreated
435→	})
436→
437→	// Read the most recent session's transcript.
438→	latestSession := sessions[0]
439→	transcriptPath := filepath.Join(sessDir, latestSession.SessionID+".json")
440→	transcriptData, err := os.ReadFile(transcriptPath) //nolint:gosec // Controlled path from IDE storage
441→	if err != nil {
442→		return "", fmt.Errorf("failed to read IDE transcript %s: %w", transcriptPath, err)
443→	}
444→
445→	// Cache the transcript under our session ID.
446→	repoRoot, rootErr := paths.WorktreeRoot(ctx)
447→	if rootErr != nil {
448→		repoRoot = cwd
449→	}
450→
451→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
452→	cachePath := filepath.Join(cacheDir, sessionID+".json")
453→
454→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
455→		return "", fmt.Errorf("failed to create cache dir: %w", err)
456→	}
457→
458→	if err := os.WriteFile(cachePath, transcriptData, 0o600); err != nil {
459→		return "", fmt.Errorf("failed to write cached IDE transcript: %w", err)
460→	}
461→
462→	logging.Info(ctx, "kiro: cached IDE transcript",
463→		"ide_session", latestSession.SessionID,
464→		"our_session", sessionID,
465→		"cache_path", cachePath,
466→	)
467→
468→	return cachePath, nil
469→}
